export function initials(name) {
  return name.split(/\s+/).map(w => w[0]).join('').slice(0, 2).toUpperCase()
}

export function todayKey() {
  const d = new Date()
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
}

// Deterministic PRNG (mulberry32)
export function rng(seed) {
  let t = seed >>> 0
  return () => {
    t += 0x6D2B79F5
    let r = Math.imul(t ^ (t >>> 15), 1 | t)
    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r)
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296
  }
}

export function hashStr(s) {
  let h = 2166136261
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return h >>> 0
}

export function dailyTarget(dateKey = todayKey()) {
  const i = hashStr(dateKey + ':target') % TARGETS.length
  return { ...TARGETS[i], id: 'target-' + dateKey }
}

export function targetAt(index) {
  const t = TARGETS[((index % TARGETS.length) + TARGETS.length) % TARGETS.length]
  return { ...t, id: 'target-u-' + index }
}

export function pickHand(dateKey, round, excludeIds, rand = rng(hashStr(dateKey + ':r' + round))) {
  const pool = SEASONS.filter(s => !excludeIds.has(s.id))
  const out = []
  const used = new Set()
  // Prefer variety of names
  while (out.length < 5 && used.size < pool.length) {
    const i = Math.floor(rand() * pool.length)
    const p = pool[i]
    if (used.has(p.id)) continue
    // Avoid same name twice in one hand when possible
    if (out.some(x => x.name === p.name) && out.length < 4) continue
    used.add(p.id)
    out.push(p)
  }
  // Fill if needed
  while (out.length < 5) {
    const i = Math.floor(rand() * pool.length)
    if (!out.includes(pool[i])) out.push(pool[i])
    else break
  }
  return out
}

/** Score a locked pick: goal is to BEAT the target (or lower TOV). */
export function scoreBeat(statKey, value, target) {
  const meta = STATS.find(s => s.key === statKey)
  const lower = meta?.lowerBetter
  if (value == null || target == null) return 0

  if (lower) {
    // Lower TOV is better
    if (value < target) {
      const margin = target - value
      return Math.min(100, Math.round(88 + margin * 12))
    }
    if (value === target) return 72
    const miss = value - target
    return Math.max(0, Math.round(55 - miss * 22))
  }

  // Higher is better
  if (value > target) {
    const margin = value - target
    const scale = Math.max(target * 0.08, statKey.includes('%') ? 2 : 0.4)
    return Math.min(100, Math.round(88 + (margin / scale) * 4))
  }
  if (value === target) return 72
  const ratio = value / Math.max(target, 0.01)
  return Math.max(0, Math.round(ratio * 65))
}

export function grade(score) {
  if (score >= 97) return 'A+'
  if (score >= 93) return 'A'
  if (score >= 90) return 'A−'
  if (score >= 87) return 'B+'
  if (score >= 83) return 'B'
  if (score >= 80) return 'B−'
  if (score >= 77) return 'C+'
  if (score >= 73) return 'C'
  if (score >= 70) return 'C−'
  if (score >= 60) return 'D'
  return 'F'
}

export function didBeat(statKey, value, target) {
  const meta = STATS.find(s => s.key === statKey)
  if (meta?.lowerBetter) return value < target
  return value > target
}
